window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f71486f87cd60375"]={"versions": [{"id": "FIG-f71486f87cd60375", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Musterspezifikation (Pattern Specification Example) im Rahmen des AUTOSAR Generic Structure Template (GST). Das Diagramm stellt eine Transformations- bzw. Generierungsvorschrift zwischen zwei Metamodell-Repräsentationen dar: dem kompakten, annotierten Metamodell (<code>annotated meta model</code>) und dem daraus resultierenden expandierten Metamodell (<code>extended meta model</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei durch eine gestrichelte Generierungsbeziehung (<code>«generates»</code>) verbundene Rahmen:</p>\n<ul class=\"fig-list\">\n<li><strong>annotated meta model</strong>:</li>\n<li>Metaklasse <code>{WholeClass}</code> als Ganzes.</li>\n<li>Metaklasse <code>{PartClass}</code> als Teil.</li>\n<li>Kompositionsbeziehung von <code>{WholeClass}</code> zu <code>{PartClass}</code> mit dem Rollennamen <code>+{partRole}</code> und dem Stereotyp <code>«atpVariation»</code>.</li>\n<li>Angehängter Notizkommentar an der Assoziation: <code>vh.latestBindingTime = {latestBindingTime}</code>.</li>\n<li><strong>extended meta model</strong>:</li>\n<li>Metaklasse <code>{WholeClass}</code> mit OCL-/Semantik-Constraint: <code>constraints {{PartRole}.variationPoint.bindingTime &lt;= {latestBindingTime}}</code>.</li>\n<li>Aggregations-/Kompositionsziel <code>{PartClass}Conditional</code>, angebunden über eine Komposition mit Rolle <code>+{partRole}</code> und Kardinalität <code>*</code>.</li>\n<li><code>{PartClass}Conditional</code> enthält zwei 1-zu-1-Kompositionen:</li>\n<li>Zu <code>VariationPoint</code> mit Rollenname <code>+variationPoint</code> und Kardinalität <code>1</code>.</li>\n<li>Zu <code>{PartClass}</code> mit Rollenname <code>+the{PartClass}</code> und Kardinalität <code>1</code>.</li>\n<li>Metaklasse <code>VariationPoint</code> mit privatem Attribut <code>- bindingTime :BindingTimeEnum</code> (rot hervorgehoben).</li>\n<li>Metaklasse <code>{PartClass}</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Musterspezifikationsdiagramm; kein dynamischer Sequenzablauf. Die gestrichelte gerichtete Abhängigkeit mit Stereotyp <code>«generates»</code> visualisiert die formale Entfaltung: Eine durch <code>«atpVariation»</code> und <code>vh.latestBindingTime</code> annotierte Beziehung im AUTOSAR-Metamodell wird deterministisch in eine explizite Bedingungsstruktur (<code>{PartClass}Conditional</code>) expandiert, die die Variationspunkte kapselt und die zulässigen Bindezeiten einschränkt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Entwurfsmuster für die generische Modellierung von Variationspunkten in AUTOSAR. Das Muster definiert verbindlich, wie Assoziationen mit <code>«atpVariation»</code> in konkrete Metamodellstrukturen überführt werden:</p>\n<ul class=\"fig-list\">\n<li>Ersetzung der direkten Assoziation durch eine mehrwertige Beziehung (<code>*</code>) zu einem intermediären Wrapper <code>{PartClass}Conditional</code>.</li>\n<li>Bindung genau eines <code>VariationPoint</code> (<code>+variationPoint [1]</code>) sowie genau einer Zielinstanz (<code>+the{PartClass} [1]</code>) je Bedingung.</li>\n<li>Erzwingung des Constraints, dass die tatsächliche Bindezeit des Variationspunkts (<code>bindingTime</code>) kleiner oder gleich der für die Aggregation definierten Maximalbindezeit (<code>latestBindingTime</code>) sein muss.</li>\n</ul>"}, {"id": "FIG-5aba54c450020c65", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Musterspezifikation (Pattern Specification Example) im Rahmen des AUTOSAR Generic Structure Template (GST). Das Diagramm stellt eine Transformations- bzw. Generierungsvorschrift zwischen zwei Metamodell-Repräsentationen dar: dem kompakten, annotierten Metamodell (<code>annotated meta model</code>) und dem daraus resultierenden expandierten Metamodell (<code>extended meta model</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei durch eine gestrichelte Generierungsbeziehung (<code>«generates»</code>) verbundene Rahmen:</p>\n<ul class=\"fig-list\">\n<li><strong>annotated meta model</strong>:</li>\n<li>Metaklasse <code>{WholeClass}</code> als Ganzes.</li>\n<li>Metaklasse <code>{PartClass}</code> als Teil.</li>\n<li>Kompositionsbeziehung von <code>{WholeClass}</code> zu <code>{PartClass}</code> mit dem Rollennamen <code>+{partRole}</code> und dem Stereotyp <code>«atpVariation»</code>.</li>\n<li>Angehängter Notizkommentar an der Assoziation: <code>vh.latestBindingTime = {latestBindingTime}</code>.</li>\n<li><strong>extended meta model</strong>:</li>\n<li>Metaklasse <code>{WholeClass}</code> mit OCL-/Semantik-Constraint: <code>constraints {{PartRole}.variationPoint.bindingTime &lt;= {latestBindingTime}}</code>.</li>\n<li>Aggregations-/Kompositionsziel <code>{PartClass}Conditional</code>, angebunden über eine Komposition mit Rolle <code>+{partRole}</code> und Kardinalität <code>*</code>.</li>\n<li><code>{PartClass}Conditional</code> enthält zwei 1-zu-1-Kompositionen:</li>\n<li>Zu <code>VariationPoint</code> mit Rollenname <code>+variationPoint</code> und Kardinalität <code>1</code>.</li>\n<li>Zu <code>{PartClass}</code> mit Rollenname <code>+the{PartClass}</code> und Kardinalität <code>1</code>.</li>\n<li>Metaklasse <code>VariationPoint</code> mit privatem Attribut <code>- bindingTime: BindingTimeEnum</code> (rot hervorgehoben).</li>\n<li>Metaklasse <code>{PartClass}</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Musterspezifikationsdiagramm; kein dynamischer Sequenzablauf. Die gestrichelte gerichtete Abhängigkeit mit Stereotyp <code>«generates»</code> visualisiert die formale Entfaltung: Eine durch <code>«atpVariation»</code> und <code>vh.latestBindingTime</code> annotierte Beziehung im AUTOSAR-Metamodell wird deterministisch in eine explizite Bedingungsstruktur (<code>{PartClass}Conditional</code>) expandiert, die die Variationspunkte kapselt und die zulässigen Bindezeiten einschränkt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Entwurfsmuster für die generische Modellierung von Variationspunkten in AUTOSAR. Das Muster definiert verbindlich, wie Assoziationen mit <code>«atpVariation»</code> in konkrete Metamodellstrukturen überführt werden:</p>\n<ul class=\"fig-list\">\n<li>Ersetzung der direkten Assoziation durch eine mehrwertige Beziehung (<code>*</code>) zu einem intermediären Wrapper <code>{PartClass}Conditional</code>.</li>\n<li>Bindung genau eines <code>VariationPoint</code> (<code>+variationPoint [1]</code>) sowie genau einer Zielinstanz (<code>+the{PartClass} [1]</code>) je Bedingung.</li>\n<li>Erzwingung des Constraints, dass die tatsächliche Bindezeit des Variationspunkts (<code>bindingTime</code>) kleiner oder gleich der für die Aggregation definierten Maximalbindezeit (<code>latestBindingTime</code>) sein muss.</li>\n</ul>"}], "trans": [{"from": "FIG-f71486f87cd60375", "to": "FIG-5aba54c450020c65", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>VariationPoint</code>: Leerzeichen bei Attributtypisierung von <code>- bindingTime :BindingTimeEnum</code> zu <code>- bindingTime: BindingTimeEnum</code> korrigiert.</li>\n</ul>"}]};
